// Package navidrome forwards Subsonic API traffic to a Navidrome server.
package navidrome

import (
	"encoding/json"
	"encoding/xml"
	"log/slog"
	"net/http"
	"net/http/httputil"
	"net/url"

	"github.com/go-chi/chi/v5/middleware"
)

// subsonicVersion is the API version reported in responses generated by apollo.
const subsonicVersion = "1.16.1"

// unavailableMessage is the client-facing message when Navidrome cannot be reached.
const unavailableMessage = "navidrome is unavailable"

// NewRestProxy returns a RestProxy that forwards requests to upstream using
// transport, or http.DefaultTransport when transport is nil. Searches that
// search intercepts are answered without reaching upstream; a nil search
// forwards everything.
func NewRestProxy(upstream *url.URL, transport http.RoundTripper, search *InterceptSearchService) *RestProxy {
	if transport == nil {
		transport = http.DefaultTransport
	}
	return &RestProxy{
		proxy: &httputil.ReverseProxy{
			Rewrite: func(r *httputil.ProxyRequest) {
				r.SetURL(upstream)
				r.SetXForwarded()
			},
			Transport: transport,
			// Flush immediately so audio streams and downloads are not buffered.
			FlushInterval: -1,
			ErrorHandler:  writeUnavailable,
		},
		search: search,
	}
}

func (p *RestProxy) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	if p.search != nil && p.search.Intercept(w, r) {
		return
	}
	p.proxy.ServeHTTP(w, r)
}

// writeUnavailable replies with a Subsonic "failed" envelope.
func writeUnavailable(w http.ResponseWriter, r *http.Request, err error) {
	slog.Error("navidrome unreachable",
		"method", r.Method,
		"path", r.URL.Path,
		"err", err,
		"request_id", middleware.GetReqID(r.Context()),
	)

	writeResponse(w, r, http.StatusBadGateway, subsonicResponse{
		Status: "failed",
		Error:  &subsonicError{Code: 0, Message: unavailableMessage},
	})
}

// writeResponse sends resp, with apollo's API version unless it carries
// Navidrome's, in the format the client asked for via the f
// parameter (JSON, or the XML default).
func writeResponse(w http.ResponseWriter, r *http.Request, status int, resp subsonicResponse) {
	if resp.Version == "" {
		resp.Version = subsonicVersion
	}

	if r.URL.Query().Get("f") == "json" {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(status)
		_ = json.NewEncoder(w).Encode(jsonEnvelope{Response: resp})
		return
	}

	resp.Xmlns = "http://subsonic.org/restapi"
	w.Header().Set("Content-Type", "application/xml")
	w.WriteHeader(status)
	_, _ = w.Write([]byte(xml.Header))
	_ = xml.NewEncoder(w).Encode(resp)
}
